from service.relation_normalize import canonical_mesh_id, parse_entities_raw

raw = state.get('entities') or []
if isinstance(raw, str):
    import json
    try:
        raw = json.loads(raw)
    except Exception:
        raw = []

ents = parse_entities_raw(raw)
by_id: dict[str, dict] = {}
for e in ents:
    txt = str(e.get('text') or '').strip()
    lbl = str(e.get('label') or e.get('type') or '').strip()
    eid = canonical_mesh_id(str(e.get('id') or e.get('identifier') or ''))
    if not txt or not lbl:
        continue
    if not eid:
        key = f"{lbl}:{txt.lower()}"
        if key not in by_id:
            by_id[key] = {"text": txt, "id": "", "label": lbl}
        continue
    if eid not in by_id or len(txt) < len(str(by_id[eid].get('text') or '')):
        by_id[eid] = {"text": txt, "id": eid, "label": lbl}

__result__ = list(by_id.values())
